BEGIN TRANSACTION;
CREATE TABLE canh_bao_hoc_vu (id INTEGER PRIMARY KEY AUTOINCREMENT, ma_canh_bao VARCHAR(50) UNIQUE NOT NULL, ma_sv VARCHAR(20) NOT NULL, hoc_ky INTEGER NOT NULL, nam_hoc VARCHAR(20) NOT NULL, muc_canh_bao VARCHAR(30) NOT NULL, gpa_xet_duyet REAL NOT NULL, ly_do TEXT, ngay_quyet_dinh DATE NOT NULL, trang_thai_tu_van VARCHAR(30) DEFAULT 'CHUA_TU_VAN');
CREATE TABLE chuyen_can_mon_hoc (id INTEGER PRIMARY KEY AUTOINCREMENT, ma_sv VARCHAR(20) NOT NULL, ma_mon VARCHAR(20) NOT NULL, ma_lop VARCHAR(20) NOT NULL, hoc_ky INTEGER DEFAULT 1, nam_hoc VARCHAR(20) DEFAULT '2025-2026', tong_so_buoi INTEGER DEFAULT 15, so_buoi_co_mat INTEGER DEFAULT 15, so_buoi_muon INTEGER DEFAULT 0, so_buoi_vang_phep INTEGER DEFAULT 0, so_buoi_vang_khong_phep INTEGER DEFAULT 0, tong_buoi_vang_quy_doi REAL DEFAULT 0.0, ty_le_vang REAL DEFAULT 0.0, diem_chuyen_can REAL DEFAULT 10.0, trang_thai_du_thi VARCHAR(30) DEFAULT 'DU_DIEU_KIEN', ly_do_cam_thi TEXT, ghi_chu TEXT);
CREATE TABLE co_van_hoc_tap (ma_cvht VARCHAR(20) PRIMARY KEY, ho_ten TEXT NOT NULL, email TEXT NOT NULL, so_dien_thoai TEXT, khoa TEXT NOT NULL);
CREATE TABLE diem_danh (id INTEGER PRIMARY KEY AUTOINCREMENT, id_lich INTEGER NOT NULL, ma_sv VARCHAR(20) NOT NULL, ngay_diem_danh DATE NOT NULL, trang_thai VARCHAR(30) DEFAULT 'CO_MAT', ghi_chu TEXT);
CREATE TABLE ket_qua_hoc_tap (id INTEGER PRIMARY KEY AUTOINCREMENT, ma_sv VARCHAR(20) NOT NULL, hoc_ky INTEGER NOT NULL, nam_hoc VARCHAR(20) NOT NULL, gpa_hoc_ky REAL NOT NULL, gpa_tich_luy REAL NOT NULL, so_tin_chi_no INTEGER DEFAULT 0, tong_tin_chi_tich_luy INTEGER DEFAULT 0, nam_thu INTEGER DEFAULT 1);
CREATE TABLE lich_giang_day (id INTEGER PRIMARY KEY AUTOINCREMENT, ma_cvht VARCHAR(20) NOT NULL, ten_cvht TEXT NOT NULL, ma_lop VARCHAR(20) NOT NULL, ten_lop TEXT NOT NULL, tieu_de TEXT NOT NULL, ngay DATE NOT NULL, gio_bat_dau VARCHAR(20) NOT NULL, gio_ket_thuc VARCHAR(20) NOT NULL, dia_diem TEXT NOT NULL, hinh_thuc VARCHAR(50) DEFAULT 'TRUC_TIEP', loai_buoi VARCHAR(50) DEFAULT 'GIANG_DAY', trang_thai VARCHAR(30) DEFAULT 'SCHEDULED', ghi_chu TEXT);
CREATE TABLE lop_hoc (ma_lop VARCHAR(20) PRIMARY KEY, ten_lop TEXT NOT NULL, khoa TEXT NOT NULL, khoa_hoc INTEGER NOT NULL, ma_cvht VARCHAR(20));
CREATE TABLE mon_hoc (ma_mon VARCHAR(20) PRIMARY KEY, ten_mon TEXT NOT NULL, so_tin_chi INTEGER NOT NULL, so_tiet INTEGER NOT NULL, so_buoi_toi_da_vang INTEGER NOT NULL, khoa TEXT NOT NULL);
CREATE TABLE nhat_ky_he_thong (id INTEGER PRIMARY KEY AUTOINCREMENT, ten_dang_nhap VARCHAR(50) NOT NULL, ho_ten TEXT NOT NULL, vai_tro VARCHAR(30) NOT NULL, loai_hanh_dong VARCHAR(50) NOT NULL, mo_ta_chi_tiet TEXT NOT NULL, dia_chi_ip VARCHAR(50) DEFAULT '127.0.0.1', thiet_bi TEXT DEFAULT 'Java Swing Desktop', thoi_gian DATETIME DEFAULT CURRENT_TIMESTAMP, trang_thai_phien VARCHAR(30) DEFAULT 'ONLINE');
CREATE TABLE nhat_ky_tu_van (id INTEGER PRIMARY KEY AUTOINCREMENT, ma_sv VARCHAR(20) NOT NULL, ma_cvht VARCHAR(20) NOT NULL, id_canh_bao INTEGER, ngay_tu_van DATE NOT NULL, hinh_thuc TEXT NOT NULL, noi_dung TEXT NOT NULL, nguyen_nhan TEXT, giai_phap TEXT, cam_ket_sinh_vien TEXT);
CREATE TABLE phien_dang_nhap (id INTEGER PRIMARY KEY AUTOINCREMENT, ten_dang_nhap VARCHAR(50) UNIQUE NOT NULL, ho_ten TEXT NOT NULL, vai_tro VARCHAR(30) NOT NULL, thoi_gian_dang_nhap DATETIME DEFAULT CURRENT_TIMESTAMP, thoi_gian_dang_xuat DATETIME, trang_thai VARCHAR(30) DEFAULT 'ONLINE', dia_chi_ip VARCHAR(50) DEFAULT '127.0.0.1', thiet_bi TEXT DEFAULT 'Java Swing Desktop');
CREATE TABLE sinh_vien (ma_sv VARCHAR(20) PRIMARY KEY, ho_ten TEXT NOT NULL, ngay_sinh DATE NOT NULL, gioi_tinh TEXT NOT NULL, email TEXT NOT NULL, so_dien_thoai TEXT, ma_lop VARCHAR(20) NOT NULL, trang_thai VARCHAR(30) DEFAULT 'DANG_HOC', tong_tin_chi_tich_luy INTEGER DEFAULT 0, nam_thu INTEGER DEFAULT 1);
CREATE TABLE tai_khoan (id INTEGER PRIMARY KEY AUTOINCREMENT, ten_dang_nhap VARCHAR(50) UNIQUE NOT NULL, mat_khau TEXT NOT NULL, ho_ten TEXT NOT NULL, email TEXT NOT NULL, vai_tro VARCHAR(20) NOT NULL, ma_ref VARCHAR(20), ngay_tao DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE thong_bao (id INTEGER PRIMARY KEY AUTOINCREMENT, ma_thong_bao VARCHAR(50) UNIQUE NOT NULL, tieu_de TEXT NOT NULL, noi_dung TEXT NOT NULL, nhom_rui_ro VARCHAR(30) DEFAULT 'ALL', ma_lop VARCHAR(20) DEFAULT 'ALL', ma_sv VARCHAR(20), ngay_gui DATETIME DEFAULT CURRENT_TIMESTAMP, nguoi_gui TEXT, so_luong_nhan INTEGER DEFAULT 0, trang_thai VARCHAR(30) DEFAULT 'DA_GUI');
